sketch.css:
.np{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.np *{box-sizing:border-box}
.head{display:flex;justify-content:space-between;align-items:flex-start}
.totals{display:flex;gap:20px}
.tot .tl{color:var(--muted);font-size:11.5px;font-weight:500}
.tot .tv{font-size:20px;font-weight:700;letter-spacing:-.01em;line-height:1.2}
.tot .tv small{font-size:12px;font-weight:500;color:var(--muted);margin-left:3px}
.tot.long .tv{color:var(--green)}
.tot.short .tv{color:var(--red)}
.tot.alert .tv{color:var(--red)}
.views{display:flex;gap:2px;background:var(--background);border-radius:8px;padding:2px}
.view{padding:2px 9px;border-radius:6px;font-size:11.5px;font-weight:500;color:var(--muted);cursor:pointer}
.view:hover{color:var(--text)}
.view.selected{background:var(--window);color:var(--accent);box-shadow:0 1px 2px rgba(20,20,50,.1)}
.legend{display:flex;gap:14px;font-size:11.5px;color:var(--muted)}
.legend i{display:inline-block;width:10px;height:8px;border-radius:2px;margin-right:5px;vertical-align:middle;background:var(--c)}
.legend i.dash{height:0;border-top:1.5px dashed var(--red);background:none}
.ladder{flex:1;overflow:auto;border-top:1px solid var(--border)}
.colhead,.row{display:grid;grid-template-columns:58px 1fr 76px 52px;gap:10px;align-items:center}
.colhead{font-size:11px;font-weight:600;color:var(--muted);padding:6px 6px 4px;text-transform:uppercase;letter-spacing:.03em}
.colhead .r{text-align:right}
.row{padding:5px 6px;border-radius:6px;cursor:pointer}
.row:hover{background:var(--hover)}
.row.selected{background:var(--hover);box-shadow:inset 3px 0 0 var(--accent)}
.month{font-weight:600}
.bars{position:relative;height:26px}
.axis{position:absolute;left:50%;top:-5px;bottom:-5px;width:1px;background:var(--border)}
.limit{position:absolute;top:-5px;bottom:-5px;width:0;border-left:1.5px dashed color-mix(in srgb,var(--red) 70%,transparent)}
.bar{position:absolute;border-radius:3px}
.bar.long{top:2px;height:9px;background:var(--green)}
.bar.short{top:2px;height:9px;background:var(--red)}
.bar.hedge{top:14px;height:7px;background:var(--accent);opacity:.8}
.bar.net{top:5px;height:16px}
.bar.net.pos{background:var(--green)}
.bar.net.neg{background:var(--red)}
.tick{position:absolute;top:0;bottom:0;width:3px;margin-left:-1.5px;border-radius:2px;background:var(--text)}
.net{text-align:right;font-weight:700;font-variant-numeric:tabular-nums}
.net.pos{color:var(--green)}
.net.neg{color:var(--red)}
.net.over{text-decoration:underline wavy var(--red);text-underline-offset:3px}
.ratio{text-align:right;font-size:12px;color:var(--muted);font-variant-numeric:tabular-nums}
.total{border-top:1px solid var(--border);margin-top:4px;padding-top:7px;cursor:default}
.total:hover{background:none}
.empty{color:var(--muted);text-align:center;padding:30px 0}

sketch.js:
function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const unit = props.unit || 'kgal';
  const view = props.view || 'gross';
  const limit = Math.abs(+props.limit || 0);
  const rows = (props.months || []).map(m => {
    const L = +m.physicalLong || 0, S = +m.physicalShort || 0, F = +m.futures || 0;
    return { month: m.month, L: L, S: S, F: F, net: L - S + F, ratio: Math.abs(L - S) ? Math.min(999, Math.abs(F) / Math.abs(L - S) * 100) : 0 };
  });
  const fmt = v => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(Math.round(v)).toLocaleString();

  // totals
  const net = rows.reduce((a, r) => a + r.net, 0), phys = rows.reduce((a, r) => a + r.L - r.S, 0), fut = rows.reduce((a, r) => a + r.F, 0);
  const breaches = rows.filter(r => limit && Math.abs(r.net) > limit).length;
  root.querySelector('.totals').innerHTML =
    '<div class="tot ' + (net >= 0 ? 'long' : 'short') + '"><div class="tl">Net open position</div><div class="tv">' + fmt(net) + '<small>' + esc(unit) + '</small></div></div>' +
    '<div class="tot"><div class="tl">Physical net</div><div class="tv">' + fmt(phys) + '</div></div>' +
    '<div class="tot"><div class="tl">Futures hedge</div><div class="tv">' + fmt(fut) + '</div></div>' +
    '<div class="tot' + (breaches ? ' alert' : '') + '"><div class="tl">Limit breaches</div><div class="tv">' + breaches + '</div></div>';

  const vs = root.querySelector('.views');
  vs.innerHTML = [['gross', 'Gross'], ['net', 'Net']].map(v => '<span class="view' + (v[0] === view ? ' selected' : '') + '" data-v="' + v[0] + '">' + v[1] + '</span>').join('');
  vs.querySelectorAll('.view').forEach(el => el.onclick = () => { if (el.dataset.v !== view) fire('viewChanged', { view: el.dataset.v }); });

  root.querySelector('.legend').innerHTML = view === 'gross'
    ? '<span><i style="--c:var(--green)"></i>Purchases</span><span><i style="--c:var(--red)"></i>Sales</span>' + (props.showHedges === false ? '' : '<span><i style="--c:var(--accent)"></i>Futures</span>') + '<span><i style="--c:var(--text);width:3px"></i>Net</span>'
    : '<span><i style="--c:var(--green)"></i>Net long</span><span><i style="--c:var(--red)"></i>Net short</span>' + (limit ? '<span><i class="dash"></i>Limit ±' + limit.toLocaleString() + '</span>' : '');

  const box = root.querySelector('.ladder');
  if (!rows.length) { box.innerHTML = '<div class="empty">No positions</div>'; return; }

  // one scale for every month: gross uses the largest leg, net the largest net or the limit
  const scale = view === 'gross'
    ? Math.max.apply(null, rows.map(r => Math.max(r.L, r.S, Math.abs(r.F))).concat([1]))
    : Math.max.apply(null, rows.map(r => Math.abs(r.net)).concat([limit * 1.15, 1]));
  const pos = v => 50 + v / scale * 50;          // value -> % from left
  const span = (a, b, cls) => '<span class="bar ' + cls + '" style="left:' + Math.min(pos(a), pos(b)) + '%;width:' + Math.abs(pos(b) - pos(a)) + '%"></span>';

  const rowHtml = r => {
    let bars = '<span class="axis"></span>';
    if (view === 'gross') {
      bars += span(0, r.L, 'long') + span(0, -r.S, 'short');
      if (props.showHedges !== false) bars += span(0, r.F, 'hedge');
      bars += '<span class="tick" style="left:' + pos(r.net) + '%" title="Net ' + fmt(r.net) + '"></span>';
    } else {
      if (limit) bars += '<span class="limit" style="left:' + pos(limit) + '%"></span><span class="limit" style="left:' + pos(-limit) + '%"></span>';
      bars += span(0, r.net, 'net ' + (r.net >= 0 ? 'pos' : 'neg'));
    }
    const over = limit && Math.abs(r.net) > limit;
    return '<div class="row' + (r.month === props.selected ? ' selected' : '') + '" data-m="' + esc(r.month) + '">' +
      '<span class="month">' + esc(r.month) + '</span><div class="bars">' + bars + '</div>' +
      '<span class="net ' + (r.net >= 0 ? 'pos' : 'neg') + (over ? ' over' : '') + '">' + fmt(r.net) + '</span>' +
      '<span class="ratio">' + Math.round(r.ratio) + '%</span></div>';
  };
  box.innerHTML = '<div class="colhead"><span>Month</span><span style="text-align:center">Short ← → Long</span><span class="r">Net</span><span class="r">Hedged</span></div>' +
    rows.map(rowHtml).join('');
  box.querySelectorAll('.row').forEach(el => el.onclick = () => fire('monthSelected', { month: el.dataset.m, selected: el.dataset.m }));
}
